/**
 * Writes the App API as three paste-sized files, apps-script/paste/Part1.gs to
 * Part3.gs, for setting up or updating the Apps Script project in the browser
 * without clasp. Apps Script shares one global scope across files, so the
 * parts behave exactly like the separate source files.
 *
 * Usage (from apps-script/): npm run paste
 */
'use strict';

const fs = require('fs');
const path = require('path');
const vm = require('vm');
const { orderFiles } = require('../test/harness');

const ROOT = path.join(__dirname, '..');
const OUT = path.join(ROOT, 'paste');
// Keeps each part comfortably small for the editor's paste.
const MAX_PART_BYTES = 90 * 1024;

const sources = orderFiles(fs.readdirSync(ROOT).filter(f => f.endsWith('.js')));

const parts = [[]];
let size = 0;
for (const f of sources) {
  const bytes = fs.statSync(path.join(ROOT, f)).size;
  if (size + bytes > MAX_PART_BYTES && parts[parts.length - 1].length) {
    parts.push([]);
    size = 0;
  }
  parts[parts.length - 1].push(f);
  size += bytes;
}

fs.rmSync(OUT, { recursive: true, force: true });
fs.mkdirSync(OUT);
const written = parts.map((files, i) => {
  const name = `Part${i + 1}.gs`;
  const body = files.map(f => `// ===== ${f} =====\n` + fs.readFileSync(path.join(ROOT, f), 'utf8')).join('\n');
  const text = `// Vehicles App API, part ${i + 1} of ${parts.length}: ${files.join(', ')}.\n` +
    '// Generated by apps-script/tools/paste-bundle.js. Edit the source files, not this.\n\n' + body;
  fs.writeFileSync(path.join(OUT, name), text);
  return [name, text];
});
fs.copyFileSync(path.join(ROOT, 'appsscript.json'), path.join(OUT, 'appsscript.json'));

// The parts must define exactly the globals the separate files do.
function globalsOf(scripts) {
  const context = vm.createContext({});
  for (const [name, text] of scripts) vm.runInContext(text, context, { filename: name });
  return new Set(vm.runInContext('Object.getOwnPropertyNames(globalThis)', context));
}
const expected = globalsOf(sources.map(f => [f, fs.readFileSync(path.join(ROOT, f), 'utf8')]));
const actual = globalsOf(written);
const diff = [...expected].filter(g => !actual.has(g)).concat([...actual].filter(g => !expected.has(g)));
if (diff.length) throw new Error('Bundled parts define different globals: ' + diff.join(', '));

for (const [name, text] of written) console.log(`paste/${name}  ${Math.round(Buffer.byteLength(text) / 1024)} KB`);
console.log('paste/appsscript.json');
